use std::env;

fn main() {
    let args: Vec<String> = env::args().collect();
    println!("{} argument(s), counting the program's own name", args.len());
    let user_args = &args[1..];   // skip the program name
    println!("your arguments: {user_args:?}");
}

// Output:
// 1 argument(s), counting the program's own name
// your arguments: []

use std::env;
use std::fmt;

enum Mode {
    All,
    Lines,
    Words,
    Chars,
}

enum CliError {
    UnknownFlag(String),
    TooManyFlags,
}

impl fmt::Display for CliError {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        match self {
            CliError::UnknownFlag(flag) => write!(f, "unknown flag {flag}"),
            CliError::TooManyFlags => write!(f, "please give at most one flag"),
        }
    }
}

fn parse_args(args: &[String]) -> Result<Mode, CliError> {
    if args.len() > 1 {
        return Err(CliError::TooManyFlags);
    }
    match args.first() {   // first() is Some(first item), or None if args is empty
        None => Ok(Mode::All),
        Some(flag) => match flag.as_str() {
            "--lines" => Ok(Mode::Lines),
            "--words" => Ok(Mode::Words),
            "--chars" => Ok(Mode::Chars),
            other => Err(CliError::UnknownFlag(other.to_string())),
        },
    }
}

fn report(text: &str, mode: &Mode) -> String {
    let lines = text.lines().count();
    let words = text.split_whitespace().count();
    let chars = text.chars().count();
    match mode {
        Mode::Lines => format!("{lines}"),
        Mode::Words => format!("{words}"),
        Mode::Chars => format!("{chars}"),
        Mode::All => format!("{lines} lines, {words} words, {chars} characters"),
    }
}

fn run(args: &[String], text: &str) -> Result<String, CliError> {
    let mode = parse_args(args)?;
    Ok(report(text, &mode))
}

fn main() {
    let text = "the quick brown fox\njumps over\nthe lazy dog\n";

    // Pretend command lines, because the app can't pass real arguments.
    let mut runs: Vec<Vec<String>> = vec![
        vec![],
        vec![String::from("--words")],
        vec![String::from("--chars")],
        vec![String::from("--bogus")],
        vec![String::from("--lines"), String::from("--words")],
    ];
    // If you run this on your own computer with real arguments, use them instead.
    let real: Vec<String> = env::args().skip(1).collect();
    if !real.is_empty() {
        runs = vec![real];
    }

    for args in &runs {
        println!("$ counter {}", args.join(" "));   // join glues the Strings together with a space between
        match run(args, text) {
            Ok(output) => println!("{output}"),
            Err(e) => println!("error: {e}"),
        }
    }
}

// Output:
// $ counter
// 3 lines, 9 words, 44 characters
// $ counter --words
// 9
// $ counter --chars
// 44
// $ counter --bogus
// error: unknown flag --bogus
// $ counter --lines --words
// error: please give at most one flag

