fn count(text: &str, flag: &str) -> Option<usize> {
    match flag {
        "--lines" => Some(text.lines().count()),
        "--words" => Some(text.split_whitespace().count()),
        _ => None,
    }
}

fn main() {
    let text = "one two\nthree four five\n";
    for flag in ["--lines", "--words", "--chars"] {
        match count(text, flag) {
            Some(n) => println!("{flag}: {n}"),
            None => println!("{flag}: unknown flag"),
        }
    }
}

